import { beforeEach, describe, expect, it, vi } from "vitest";
import type { OnloadArgs } from "roamjs-components/types/native";

const { fireQuery } = vi.hoisted(() => ({ fireQuery: vi.fn() }));

vi.mock("~/utils/fireQuery", () => ({ default: fireQuery }));
vi.mock("~/utils/parseQuery", () => ({
  default: () => ({ conditions: [], selections: [], returnNode: "node" }),
}));
vi.mock("~/utils/parseResultSettings", () => ({ default: () => ({}) }));
vi.mock("~/utils/postProcessResults", () => ({
  default: () => ({ allProcessedResults: [] }),
}));

import runQuery from "~/utils/runQuery";

const extensionAPI = {} as OnloadArgs["extensionAPI"];

describe("runQuery", () => {
  beforeEach(() => {
    fireQuery.mockReset().mockResolvedValue([]);
    vi.stubGlobal("window", {
      roamAlphaAPI: { util: { generateUID: () => "uid" } },
    });
  });

  it("forwards local so callers can read blocks the backend has not synced", async () => {
    await runQuery({
      parentUid: "q",
      extensionAPI,
      inputs: { NODETEXT: "t" },
      local: true,
    });
    expect(fireQuery).toHaveBeenCalledWith(
      expect.objectContaining({ local: true, inputs: { NODETEXT: "t" } }),
    );
  });

  it("leaves local unset by default", async () => {
    await runQuery({ parentUid: "q", extensionAPI });
    expect(fireQuery.mock.calls[0][0].local).toBeUndefined();
  });
});

