export default {
  async run({ page }) {
    return page.evaluate(async () => {
      const qb = window.roamjs?.extension?.queryBuilder;
      const nodes = qb.getDiscourseNodes();
      const api = window.roamAlphaAPI;
      const out = { qbKeys: Object.keys(qb), nodes: nodes.map(n => ({ text: n.text, type: n.type, backedBy: n.backedBy, canvasSettings: n.canvasSettings, format: n.format, spec: (n.specification||[]).map(s=>s.relation) })) };
      // settings page / flags
      const cfg = api.data.fast.q(`[:find ?uid :where [?p :node/title "roam/js/discourse-graph"] [?p :block/uid ?uid]]`);
      out.configPage = cfg;
      if (cfg[0]) {
        const pull = api.pull("[:block/props :block/uid]", [":block/uid", cfg[0][0]]);
        out.configProps = JSON.stringify(pull?.[":block/props"] || null).slice(0, 3000);
      }
      const first = nodes.find(n => n.backedBy === "user");
      if (first) {
        const tree = api.pull("[:node/title :block/uid :block/props {:block/children [:block/string :block/uid :block/order :block/heading :block/props {:block/children ...}]}]", [":block/uid", first.type]);
        out.firstNodeTree = JSON.stringify(tree).slice(0, 6000);
      }
      return out;
    });
  },
};
