        full: `[:find ?uid :in $ ?t :where [?p :node/title ?t] [?b :block/page ?p] [?h1 :block/children ?b] [?h1 :block/heading 1] [?b :block/uid ?uid]]`,
      };
      out.manual = {};
      for (const [k, q] of Object.entries(decomposed)) {
        out.manual[k] = { backend: await api.data.backend.q(q, title), local: await api.data.async.fast.q(q, title) };
      }
      return out;
    }, { t: state.canvasTitle, nodeTypeText: NODE_TYPE_TEXT });
    state.nodePageUid = result.pageTree?.[":block/uid"];
    result.recordedQueries = await page.evaluate(() => window.__eng2362Q || null);
    result.events = await page.evaluate(() => window.__eng2362Ev || null);
    return { setup, nodeContent: state.nodeContent, ...result, logs };
  },
  async cleanup({ page }) {
    const verify = await page.evaluate(async (s) => {
      const api = window.roamAlphaAPI;
      if (s.nodePageUid) await api.data.page.delete({ page: { uid: s.nodePageUid } });
      if (s.canvasUid) await api.data.page.delete({ page: { uid: s.canvasUid } });
      const verify = {};
      if (s.orig) {
        if (window.__eng2362OrigQ) api.data.backend.q = window.__eng2362OrigQ;
        if (window.__eng2362Sb) window.roamjs.extension.smartblocks = window.__eng2362Sb;
        if (window.__eng2362OrigT) window.roamjs.extension.smartblocks.triggerSmartblock = window.__eng2362OrigT;
        if (window.__eng2362OrigL) api.data.async.fast.q = window.__eng2362OrigL;
        await api.data.block.delete({ block: { uid: s.orig.childUid } });
        await api.data.block.update({ block: { uid: "fkc79sI3y", props: s.orig.props } });
        await new Promise((r) => setTimeout(r, 1000));
        const canon = (o) => JSON.stringify(o, (k, v) => (v && typeof v === "object" && !Array.isArray(v) ? Object.fromEntries(Object.entries(v).sort()) : v));
        const rawNow = api.pull("[:block/props]", [":block/uid", "fkc79sI3y"])[":block/props"];
        verify.propsRestored = canon(rawNow) === canon(JSON.parse(s.orig.raw));
        verify.keyImageChildren = api.pull("[{:block/children [:block/uid]}]", [":block/uid", "Od9f2XCkW"])?.[":block/children"] || null;
      }
      verify.nodePageGone = !s.nodePageUid || !api.pull("[:block/uid]", [":block/uid", s.nodePageUid]);
      verify.canvasGone = !api.pull("[:block/uid]", [":block/uid", s.canvasUid]);
      return verify;
    }, state);
    return { ...state, orig: state.orig ? "(backed up)" : null, verify };
  },
};

